// ------------------------------------------------------------ helpers
const now = () => system.currentTick;
const rand = (a, b) => a + Math.random() * (b - a);
const pick = (list) => list[Math.floor(Math.random() * list.length)];
const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
const valid = (e) => {
  try {
    return !!e && e.isValid;
  } catch {
    return false;
  }
};

const states = new Map(); // wolf id -> runtime state
let byOwner = new Map(); // player id -> [wolves]
const lastOwnerMessage = new Map(); // player id -> tick

function st(wolf) {
  let s = states.get(wolf.id);
  if (!s) {
    const t = now();
    s = {
      cd: {}, lastSay: -9999, talkUntil: 0, memeUntil: 0, busyUntil: 0, lastHurt: -9999, lastRegen: t,
      nextMeme: t + rand(...CFG.meme_every) * SECOND,
      nextJoke: t + rand(...CFG.joke_every) * SECOND,
      nextChatter: t + rand(...CFG.chatter_every) * SECOND,
      nextPrank: t + rand(...CFG.prank_every) * SECOND,
      paso: 0, clima: undefined, awayDim: undefined, lastDist: 0, stuck: 0, gaveUp: false,
      afk: 0, lastOwnerPos: undefined, sleeping: false,
    };
    states.set(wolf.id, s);
  }
  return s;
}

// true (and starts the cooldown) when the cooldown `key` is over
function ready(s, key, seconds) {
  if (now() < (s.cd[key] ?? 0)) return false;
  s.cd[key] = now() + seconds * SECOND;
  return true;
}

function tameable(wolf) {
  try {
    return wolf.getComponent("minecraft:tameable");
  } catch {
    return undefined;
  }
}

function isTamed(wolf) {
  try {
    return !!wolf.getComponent("minecraft:is_tamed");
  } catch {
    return false;
  }
}

// The owner's id is saved on the wolf (the tameable component may be gone once it is tamed).
function ownerIdOf(wolf) {
  if (!isTamed(wolf)) return undefined;
  try {
    let id = wolf.getDynamicProperty("lobo:dueno");
    if (!id) {
      id = tameable(wolf)?.tamedToPlayerId;
      if (id) wolf.setDynamicProperty("lobo:dueno", id);
    }
    return id || undefined;
  } catch {
    return undefined;
  }
}

function ownerOf(wolf) {
  const id = ownerIdOf(wolf);
  if (!id) return undefined;
  try {
    const p = world.getEntity(id);
    return valid(p) && p.typeId === "minecraft:player" ? p : undefined;
  } catch {
    return undefined;
  }
}

function setOwner(wolf, player) {
  try {
    wolf.setDynamicProperty("lobo:dueno", player.id);
  } catch {}
}

function nameOf(wolf) {
  try {
    return wolf.nameTag || wolf.getDynamicProperty("lobo:nombre") || "Lobo Bromista";
  } catch {
    return "Lobo Bromista";
  }
}

function setProp(wolf, key, value) {
  try {
    if (wolf.getProperty(key) !== value) wolf.setProperty(key, value);
  } catch {}
}

function silenced(player) {
  try {
    return !!player?.getDynamicProperty("lobo:silencio");
  } catch {
    return false;
  }
}

function fill(text, wolf, player, extra = {}) {
  return text
    .replaceAll("{player}", player?.name ?? "humano")
    .replaceAll("{name}", nameOf(wolf))
    .replaceAll("{dim}", extra.dim ?? "")
    .replace("{o}", "o".repeat(8 + Math.floor(Math.random() * 14)));
}

// The wolf writes in the chat: everyone sees it, with the wolf's name.
// force: skip the "don't talk too often" gap (jokes and sequences).
function say(wolf, text, player, { force = false, extra } = {}) {
  if (!valid(wolf)) return false;
  const s = st(wolf);
  const owner = player ?? ownerOf(wolf);
  if (silenced(owner)) return false;
  if (!force && now() - s.lastSay < CFG.message_gap * SECOND) return false;
  const msg = fill(text, wolf, owner, extra);
  world.sendMessage(`§6<${nameOf(wolf)}>§r ${msg}`);
  s.lastSay = now();
  if (owner) lastOwnerMessage.set(owner.id, now());
  // mouth moves while "talking", with a little bark
  s.talkUntil = now() + Math.min(80, 20 + msg.length);
  setProp(wolf, "lobo:habla", true);
  try {
    wolf.dimension.playSound("mob.wolf.bark", wolf.location, { volume: 0.7, pitch: rand(1.0, 1.4) });
  } catch {}
  return true;
}

// Several lines, one after another (gap in ticks).
function sayLines(wolf, lines, player, gap = 50, done) {
  st(wolf).busyUntil = now() + gap * lines.length + 20;
  lines.forEach((line, i) => system.runTimeout(() => {
    if (valid(wolf)) say(wolf, line, player, { force: true });
    if (i === lines.length - 1 && done) done();
  }, i * gap));
}

function meme(wolf, id, talk = false, player) {
  const m = CFG.memes[String(id)];
  if (!m || !valid(wolf)) return;
  const s = st(wolf);
  setProp(wolf, "lobo:meme", Number(id));
  s.memeUntil = now() + m.ticks;
  if (talk && m.line) say(wolf, m.line, player);
}

function randomMeme(wolf, talk, player) {
  meme(wolf, 1 + Math.floor(Math.random() * Object.keys(CFG.memes).length), talk, player);
}

function particles(wolf, id, count = 1, spread = 0.4) {
  for (let i = 0; i < count; i++) {
    const l = wolf.location;
    try {
      wolf.dimension.spawnParticle(id, { x: l.x + rand(-spread, spread), y: l.y + 0.6 + rand(0, spread),
                                         z: l.z + rand(-spread, spread) });
    } catch {}
  }
}

// The closest tamed wolf of a player that can "see" what happens.
function wolfFor(player, radius = CFG.react_radius) {
  let best;
  let bestD = radius;
  for (const w of byOwner.get(player.id) ?? []) {
    if (!valid(w) || w.dimension.id !== player.dimension.id) continue;
    const d = dist(w.location, player.location);
    if (d <= bestD) {
      best = w;
      bestD = d;
    }
  }
  return best;
}

function react(player, key, cd, chance = 1) {
  const wolf = wolfFor(player);
  if (!wolf || Math.random() > chance) return undefined;
  if (!ready(st(wolf), key, cd)) return undefined;
  return say(wolf, pick(REACT[key] ?? [key]), player) ? wolf : undefined;
}

// ------------------------------------------------------------ jokes and pranks
function badumTss(wolf) {
  const d = wolf.dimension;
  const at = wolf.location;
  const play = (id, pitch, t) => system.runTimeout(() => {
    try {
      d.playSound(id, at, { volume: 1, pitch });
    } catch {}
  }, t);
  play("note.snare", 1.0, 0);
  play("note.bd", 0.8, 5);
  play("note.hat", 1.3, 11);
  play("note.hat", 1.6, 13);
}

function tellJoke(wolf, player) {
  if (!valid(wolf) || now() < st(wolf).busyUntil) return false;
  const joke = pick(JOKES);
  sayLines(wolf, joke, player, 60, () => {
    if (!valid(wolf)) return;
    badumTss(wolf);
    system.runTimeout(() => {
      if (!valid(wolf)) return;
      if (Math.random() < 0.55) {
        meme(wolf, 10);
        say(wolf, pick(AFTER_JOKE_LAUGH), player, { force: true });
      } else {
        meme(wolf, 9);
        say(wolf, pick(AFTER_JOKE_SILENCE), player, { force: true });
      }
    }, 40);
  });
  return true;
}

function behind(player, blocks) {
  const v = player.getViewDirection();
  const len = Math.hypot(v.x, v.z) || 1;
  const p = player.location;
  return { x: p.x - (v.x / len) * blocks, y: p.y + 1, z: p.z - (v.z / len) * blocks };
}

function prank(wolf, player) {
  if (!valid(wolf) || !valid(player) || now() < st(wolf).busyUntil) return false;
  st(wolf).busyUntil = now() + 6 * SECOND;
  const kind = pick(["creeper", "creeper", "bu", "logro", "diamante", "espalda", "lamer"]);
  switch (kind) {
    case "creeper":
      // a creeper hiss right behind the player
      player.playSound("random.fuse", { location: behind(player, 1.5), volume: 1, pitch: 1 });
      system.runTimeout(() => {
        if (!valid(wolf)) return;
        meme(wolf, 10);
        say(wolf, pick(PRANK_LINES.creeper), player, { force: true });
      }, 35);
      break;
    case "bu": {
      const p = player.location;
      const w = wolf.location;
      const len = Math.hypot(p.x - w.x, p.z - w.z) || 1;
      try {
        wolf.applyImpulse({ x: ((p.x - w.x) / len) * 0.5, y: 0.45, z: ((p.z - w.z) / len) * 0.5 });
      } catch {}
      try {
        wolf.dimension.playSound("mob.wolf.growl", wolf.location, { volume: 1.5, pitch: 0.7 });
      } catch {}
      meme(wolf, 12);
      say(wolf, pick(PRANK_LINES.bu), player, { force: true });
      system.runTimeout(() => valid(wolf) && say(wolf, pick(PRANK_LINES.bu2), player, { force: true }), 30);
      break;
    }
    case "logro":
      world.sendMessage(`§e${player.name} ha conseguido el logro §a[Tener al mejor lobo del mundo]`);
      try {
        player.playSound("random.levelup", { volume: 0.8 });
      } catch {}
      system.runTimeout(() => valid(wolf) && (meme(wolf, 11), say(wolf, pick(PRANK_LINES.logro), player, { force: true })), 40);
      break;
    case "lamer":
      particles(wolf, "minecraft:heart_particle", 4, 0.6);
      say(wolf, pick(PRANK_LINES.lamer), player, { force: true });
      break;
    default: {
      const lines = PRANK_LINES[kind];
      sayLines(wolf, lines, player, 60, () => valid(wolf) && meme(wolf, 10));
    }
  }
  return true;
}

// ------------------------------------------------------------ the main loop
function scan() {
  const map = new Map();
  const all = [];
  for (const id of DIMENSIONS) {
    let list = [];
    try {
      list = world.getDimension(id).getEntities({ type: ID });
    } catch {}
    for (const w of list) {
      all.push(w);
      const owner = ownerIdOf(w);
      if (!owner) continue;
      if (!map.has(owner)) map.set(owner, []);
      map.get(owner).push(w);
    }
  }
  byOwner = map;
  return all;
}

function speedUp(wolf, paso) {
  if (paso === 0) return;
  try {
    wolf.addEffect("speed", 30, { amplifier: paso === 2 ? CFG.sprint_speed : CFG.trot_speed, showParticles: false });
  } catch {}
}

// Instead of teleporting like a normal wolf, it speeds up (and leaps) to catch up.
function follow(wolf, s, owner) {
  const sitting = !!wolf.getProperty("lobo:sentado");
  const d = dist(wolf.location, owner.location);

  if (sitting) {
    setProp(wolf, "lobo:paso", 0);
    s.paso = 0;
    if (d > 24 && ready(s, "sitFar", 240)) say(wolf, pick(MOVE.sitFar), owner);
    return d;
  }
  if (d > CFG.give_up_dist) {
    if (!s.gaveUp) {
      s.gaveUp = true;
      say(wolf, pick(MOVE.giveUp), owner);
    }
    setProp(wolf, "lobo:paso", 0);
    s.paso = 0;
    return d;
  }
  s.gaveUp = false;

  let paso = s.paso;
  if (d > CFG.sprint_dist) paso = 2;
  else if (d > CFG.trot_dist) paso = Math.max(paso === 2 && d > CFG.trot_dist + 3 ? 2 : 1, 1);
  else if (d < CFG.calm_dist) paso = 0;
  else paso = Math.min(paso, 1);

  if (paso === 2 && s.paso < 2 && ready(s, "run", 40)) say(wolf, pick(MOVE.run), owner);
  if (paso === 2 && d > CFG.sprint_dist + 8) s.ranFar = true;
  if (paso === 0 && s.ranFar) {
    s.ranFar = false;
    if (ready(s, "arrived", 60)) say(wolf, pick(MOVE.arrived), owner);
  }
  s.paso = paso;
  setProp(wolf, "lobo:paso", paso);
  speedUp(wolf, paso);

  if (paso === 2) {
    particles(wolf, "minecraft:basic_smoke_particle", 2, 0.3);
    // Turbo leap when it is far and not getting closer.
    s.stuck = d >= s.lastDist - 0.4 ? s.stuck + 1 : 0;
    if (d > CFG.leap_dist && (s.stuck >= 3 || d > CFG.leap_dist * 1.6) && wolf.isOnGround && ready(s, "leap", CFG.leap_cooldown)) {
      const w = wolf.location;
      const o = owner.location;
      const len = Math.hypot(o.x - w.x, o.z - w.z) || 1;
      try {
        wolf.applyImpulse({ x: ((o.x - w.x) / len) * CFG.leap_force, y: CFG.leap_up, z: ((o.z - w.z) / len) * CFG.leap_force });
      } catch {}
      particles(wolf, "minecraft:basic_crit_particle", 6, 0.5);
      s.stuck = 0;
    }
  }
  s.lastDist = d;
  return d;
}

function greet(wolf, owner) {
  let name = wolf.nameTag;
  if (!name) {
    name = pick(NAMES);
    try {
      wolf.nameTag = name;
    } catch {}
  }
  wolf.setDynamicProperty("lobo:nombre", name);
  wolf.setDynamicProperty("lobo:saludo", true);
  particles(wolf, "minecraft:heart_particle", 6, 0.6);
  meme(wolf, 8);
  sayLines(wolf, pick(GREETING), owner, 70);
}

function wildTick(wolf, s) {
  if (!ready(s, "wildCheck", 2)) return;
  for (const p of wolf.dimension.getPlayers({ location: wolf.location, maxDistance: 6 })) {
    let hand;
    try {
      hand = p.getComponent("minecraft:equippable")?.getEquipment(EquipmentSlot.Mainhand);
    } catch {}
    if (hand?.typeId === "minecraft:bone" && ready(s, "wildSee", 40)) {
      say(wolf, pick(PET.wildSee), p);
      meme(wolf, 9);
      return;
    }
  }
}

function regen(wolf, s) {
  if (now() - s.lastRegen < CFG.regen_every * SECOND) return;
  s.lastRegen = now();
  if (now() - s.lastHurt < CFG.regen_after_hurt * SECOND) return;
  try {
    const h = wolf.getComponent("minecraft:health");
    if (h && h.currentValue < h.effectiveMax) h.setCurrentValue(Math.min(h.effectiveMax, h.currentValue + CFG.regen));
  } catch {}
}

function ownerChecks(wolf, s, owner, d) {
  const t = now();
  // AFK: the owner hasn't moved for a while
  const p = owner.location;
  if (s.lastOwnerPos && dist(p, s.lastOwnerPos) < 0.15) s.afk += 10;
  else s.afk = 0;
  s.lastOwnerPos = { x: p.x, y: p.y, z: p.z };
  if (s.afk >= CFG.afk_seconds * SECOND && d < 16 && ready(s, "afk", 300)) {
    if (Math.random() < 0.5) prank(wolf, owner);
    else say(wolf, pick(REACT.afk), owner);
  }

  // sleeping / waking up
  if (owner.isSleeping && !s.sleeping) {
    s.sleeping = true;
    if (ready(s, "sleep", 300)) say(wolf, pick(REACT.sleep), owner);
  } else if (!owner.isSleeping && s.sleeping) {
    s.sleeping = false;
    if (ready(s, "wake", 300)) system.runTimeout(() => valid(wolf) && say(wolf, pick(REACT.wake), owner), 40);
  }

  if (owner.isSwimming && d < 24 && Math.random() < 0.3 && ready(s, "swim", 180)) say(wolf, pick(REACT.swim), owner);

  // weather / light changes seen by the wolf (property set by the entity's environment sensor)
  const clima = wolf.getProperty("lobo:clima");
  if (s.clima !== undefined && clima !== s.clima && d < 32 && ready(s, "clima", 45)) {
    say(wolf, pick(CLIMA[clima] ?? CLIMA[4]), owner, { force: true });
    if (clima === 2) meme(wolf, 12);
    else if (clima === 0) meme(wolf, 11);
  }
  s.clima = clima;

  if (d > 12 || t < s.busyUntil) return;
  const quiet = t - (lastOwnerMessage.get(owner.id) ?? 0) > 15 * SECOND;
  const calm = t - s.lastHurt > 10 * SECOND;

  if (t >= s.nextMeme) {
    s.nextMeme = t + rand(...CFG.meme_every) * SECOND;
    if (calm && t >= s.memeUntil) randomMeme(wolf, quiet && Math.random() < 0.4, owner);
  }
  if (t >= s.nextJoke) {
    s.nextJoke = t + rand(...CFG.joke_every) * SECOND;
    if (calm && quiet) tellJoke(wolf, owner);
  } else if (t >= s.nextPrank) {
    s.nextPrank = t + rand(...CFG.prank_every) * SECOND;
    if (calm && quiet && d < 8) prank(wolf, owner);
  } else if (t >= s.nextChatter) {
    s.nextChatter = t + rand(...CFG.chatter_every) * SECOND;
    if (quiet) say(wolf, pick(CHATTER), owner);
  }
}

function tick() {
  const t = now();
  for (const wolf of scan()) {
    if (!valid(wolf)) continue;
    const s = st(wolf);
    // end of talking / meme
    if (s.talkUntil && t >= s.talkUntil) {
      s.talkUntil = 0;
      setProp(wolf, "lobo:habla", false);
    }
    if (s.memeUntil && t >= s.memeUntil) {
      s.memeUntil = 0;
      setProp(wolf, "lobo:meme", 0);
    }
    if (!isTamed(wolf)) {
      wildTick(wolf, s);
      continue;
    }
    regen(wolf, s);
    const owner = ownerOf(wolf);
    if (!owner) continue;
    if (!wolf.getDynamicProperty("lobo:saludo")) {
      greet(wolf, owner);
      continue;
    }
    // owner in another dimension: it can't follow, but it complains
    if (owner.dimension.id !== wolf.dimension.id) {
      setProp(wolf, "lobo:paso", 0);
      s.paso = 0;
      if (s.awayDim === undefined) {
        s.awayDim = owner.dimension.id;
        if (ready(s, "otherDim", 120)) say(wolf, pick(MOVE.otherDim), owner, { extra: { dim: DIM_NAMES[wolf.dimension.id] } });
      }
      continue;
    }
    if (s.awayDim !== undefined) {
      const dim = DIM_NAMES[s.awayDim] ?? "más allá";
      s.awayDim = undefined;
      if (ready(s, "backDim", 60)) say(wolf, pick(MOVE.backDim), owner, { extra: { dim } });
    }
    const d = follow(wolf, s, owner);
    ownerChecks(wolf, s, owner, d);
  }
}
system.runInterval(tick, 10);

// day / night
let wasNight;
system.runInterval(() => {
  const time = world.getTimeOfDay();
  const night = time >= 13000 && time < 23000;
  if (wasNight !== undefined && night !== wasNight) {
    for (const player of world.getPlayers()) {
      const wolf = wolfFor(player, 24);
      if (wolf && ready(st(wolf), "daynight", 300)) say(wolf, pick(night ? REACT.night : REACT.day), player);
    }
  }
  wasNight = night;
}, 100);

// sneaking several times in a row ("gamer salute")
const sneaks = new Map();
system.runInterval(() => {
  for (const player of world.getPlayers()) {
    const rec = sneaks.get(player.id) ?? { was: false, times: [] };
    const is = player.isSneaking;
    if (is && !rec.was) rec.times.push(now());
    rec.was = is;
    rec.times = rec.times.filter((x) => now() - x < 50);
    sneaks.set(player.id, rec);
    if (rec.times.length >= 4) {
      rec.times = [];
      const wolf = react(player, "sneak", 60);
      if (wolf) meme(wolf, 1);
    }
  }
}, 2);

// ------------------------------------------------------------ reactions
world.afterEvents.entityHurt.subscribe(({ hurtEntity, damageSource, damage }) => {
  if (!valid(hurtEntity)) return;
  if (hurtEntity.typeId === ID) {
    const s = st(hurtEntity);
    s.lastHurt = now();
    const owner = ownerOf(hurtEntity);
    if (!owner) return;
    const h = hurtEntity.getComponent("minecraft:health");
    if (h && h.currentValue < h.effectiveMax * 0.25 && ready(s, "hurtLow", 30)) say(hurtEntity, pick(REACT.hurtLow), owner);
    else if (Math.random() < 0.25 && ready(s, "hurt", 40)) say(hurtEntity, pick(REACT.hurt), owner);
    return;
  }
  if (hurtEntity.typeId !== "minecraft:player" || !byOwner.has(hurtEntity.id)) return;
  const player = hurtEntity;
  const cause = damageSource.cause;
  const C = EntityDamageCause;
  let wolf;
  if (cause === C.fall && damage >= 3) wolf = react(player, "fall", 25);
  else if (cause === C.lava) wolf = react(player, "lava", 30);
  else if (cause === C.fire || cause === C.fireTick) wolf = react(player, "fire", 40);
  else if (cause === C.entityExplosion || cause === C.blockExplosion) wolf = react(player, "boom", 20);
  else if (cause === C.drowning) wolf = react(player, "drown", 40);
  else if (cause === C.contact) wolf = react(player, "cactus", 60);
  else if (cause === C.freezing) wolf = react(player, "freeze", 60);
  else if (cause === C.starve) wolf = react(player, "starve", 60);
  else if (cause === C.lightning) wolf = react(player, "lightning", 30);
  else if ((cause === C.entityAttack || cause === C.projectile) && damageSource.damagingEntity?.typeId !== "minecraft:player") {
    wolf = react(player, "mob", 30, 0.5);
  }
  if (wolf && cause === C.fall) meme(wolf, 10);
  const h = player.getComponent("minecraft:health");
  if (h && h.currentValue > 0 && h.currentValue <= 6) react(player, "low", 60);
});

world.afterEvents.entityDie.subscribe(({ deadEntity, damageSource }) => {
  let type;
  try {
    type = deadEntity.typeId;
  } catch {
    return;
  }
  // the owner died
  if (type === "minecraft:player" && byOwner.has(deadEntity.id)) {
    const wolf = wolfFor(deadEntity, 64);
    if (wolf) {
      say(wolf, pick(REACT.death), deadEntity, { force: true });
      meme(wolf, 4);
      st(wolf).ownerDied = true;
    }
    return;
  }
  // the wolf died: last words
  if (type === ID) {
    try {
      const owner = ownerOf(deadEntity);
      if (owner && !silenced(owner)) {
        const name = nameOf(deadEntity);
        world.sendMessage(`§6<${name}>§r ${fill(pick(REACT.wolfDeath), deadEntity, owner)}`);
      }
    } catch {}
    states.delete(deadEntity.id);
    return;
  }
  const killer = damageSource.damagingEntity;
  if (!valid(killer)) return;
  if (killer.typeId === ID) {
    const owner = ownerOf(killer);
    if (owner && Math.random() < 0.3 && ready(st(killer), "wolfKill", 60)) say(killer, pick(WOLF_KILL), owner);
    return;
  }
  if (killer.typeId !== "minecraft:player" || !byOwner.has(killer.id)) return;
  const wolf = wolfFor(killer);
  if (!wolf) return;
  const lines = KILLS[type];
  if (lines) {
    if (ready(st(wolf), `kill:${type}`, 20)) say(wolf, pick(lines), killer);
  } else if (Math.random() < 0.15 && ready(st(wolf), "kill", 90)) say(wolf, pick(KILL_GENERIC), killer);
});

world.afterEvents.entityHitEntity.subscribe(({ damagingEntity, hitEntity }) => {
  if (!valid(damagingEntity) || !valid(hitEntity)) return;
  // someone hits the wolf (players can't hurt a tamed one)
  if (hitEntity.typeId === ID && damagingEntity.typeId === "minecraft:player") {
    const owner = ownerOf(hitEntity);
    if (!owner) return;
    const s = st(hitEntity);
    if (!ready(s, "hit", 15)) return;
    if (damagingEntity.id === owner.id) {
      meme(hitEntity, 4);
      say(hitEntity, pick(REACT.hitByOwner), owner);
    } else say(hitEntity, pick(REACT.hitByOther), owner);
    return;
  }
  // critical bite: a second bite right after the first one
  if (damagingEntity.typeId === ID && isTamed(damagingEntity) && Math.random() < CFG.crit_chance) {
    const wolf = damagingEntity;
    const target = hitEntity;
    system.runTimeout(() => {
      if (!valid(wolf) || !valid(target)) return;
      try {
        target.applyDamage(CFG.crit_damage, { cause: EntityDamageCause.entityAttack, damagingEntity: wolf });
        target.dimension.spawnParticle("minecraft:critical_hit_emitter", { ...target.location, y: target.location.y + 1 });
      } catch {}
      try {
        ownerOf(wolf)?.onScreenDisplay.setActionBar(`§6¡Mordisco crítico de ${nameOf(wolf)}!`);
      } catch {}
    }, 11);
  }
});

world.afterEvents.playerBreakBlock.subscribe(({ player, brokenBlockPermutation }) => {
  if (!byOwner.has(player.id)) return;
  const id = brokenBlockPermutation.type.id.replace("minecraft:", "");
  const rule = BLOCKS.find((r) => (r.ids && r.ids.includes(id)) || (r.suffix && id.endsWith(r.suffix)));
  if (!rule || Math.random() > rule.chance) return;
  const wolf = wolfFor(player, 24);
  if (wolf && ready(st(wolf), `block:${rule.ids?.[0] ?? rule.suffix}`, rule.cd)) {
    if (say(wolf, pick(rule.lines), player) && rule.chance === 1) meme(wolf, Math.random() < 0.5 ? 8 : 13);
  }
});

world.afterEvents.playerPlaceBlock.subscribe(({ player }) => {
  if (!byOwner.has(player.id) || Math.random() > 0.03) return;
  const wolf = wolfFor(player, 24);
  if (wolf && ready(st(wolf), "place", 120)) say(wolf, pick(PLACE), player);
});

world.afterEvents.itemCompleteUse.subscribe(({ source: player, itemStack }) => {
  if (!itemStack || player?.typeId !== "minecraft:player" || !byOwner.has(player.id)) return;
  const special = FOOD[itemStack.typeId];
  const wolf = wolfFor(player, 16);
  if (!wolf) return;
  if (special) {
    if (ready(st(wolf), `food:${itemStack.typeId}`, 60)) say(wolf, pick(special), player);
  } else if (Math.random() < 0.3 && ready(st(wolf), "food", 90)) {
    if (say(wolf, pick(FOOD_GENERIC), player)) meme(wolf, 9);
  }
});

world.afterEvents.playerInteractWithEntity.subscribe(({ player, target, beforeItemStack }) => {
  if (!valid(target) || target.typeId !== ID) return;
  const item = beforeItemStack?.typeId;
  const s = st(target);
  if (item === "minecraft:bone" && isTamed(target) && !target.getDynamicProperty("lobo:dueno")) {
    setOwner(target, player); // tamed with this very bone
    return;
  }
  if (!isTamed(target)) {
    if (item !== "minecraft:bone") return;
    // tamed now? remember the owner (the loop greets it). Still wild: it complains.
    system.runTimeout(() => {
      if (!valid(target)) return;
      if (isTamed(target)) {
        if (!target.getDynamicProperty("lobo:dueno")) setOwner(target, player);
      } else if (ready(s, "wildBone", 8)) say(target, pick(PET.wildBone), player);
    }, 3);
    return;
  }
  const owner = ownerOf(target);
  if (owner && owner.id !== player.id) {
    if (ready(s, "petOther", 30)) say(target, pick(PET.other), owner);
    return;
  }
  if (item === "minecraft:bone") {
    if (ready(s, "petBone", 20)) say(target, pick(PET.bone), player);
  } else if (item === "minecraft:cookie") {
    if (ready(s, "petCookie", 20)) {
      meme(target, 12);
      say(target, pick(PET.cookie), player);
    }
  } else if (item && HEAL_FOODS.includes(item)) {
    if (ready(s, "petFood", 15)) {
      particles(target, "minecraft:heart_particle", 3, 0.5);
      say(target, pick(PET.meat), player);
    }
  } else if (!item) {
    // empty hand toggles sitting
    const before = !!target.getProperty("lobo:sentado");
    system.runTimeout(() => {
      if (!valid(target)) return;
      const after = !!target.getProperty("lobo:sentado");
      if (after !== before && Math.random() < 0.6 && ready(s, "sit", 20)) say(target, pick(after ? PET.sit : PET.stand), player);
    }, 3);
  }
});

world.afterEvents.playerSpawn.subscribe(({ player, initialSpawn }) => {
  system.runTimeout(() => {
    if (!valid(player)) return;
    const wolf = wolfFor(player, 64);
    if (!wolf) return;
    if (initialSpawn) {
      if (ready(st(wolf), "join", 60)) say(wolf, pick(REACT.join), player, { force: true });
    } else if (st(wolf).ownerDied) {
      st(wolf).ownerDied = false;
      say(wolf, pick(REACT.respawn), player, { force: true });
    }
  }, initialSpawn ? 100 : 20);
});

// Talking to the wolf in the chat (only with the Beta APIs experiment; without it this does nothing).
const chat = world.afterEvents.chatSend;
if (chat) {
  chat.subscribe(({ sender, message }) => {
    if (!byOwner.has(sender.id)) return;
    const text = message.toLowerCase();
    const wolf = wolfFor(sender, 32);
    if (!wolf) return;
    const name = nameOf(wolf).toLowerCase();
    if (!text.includes(name) && !/\b(lobo|perro|perrito|lobito)\b/.test(text)) return;
    system.runTimeout(() => {
      if (!valid(wolf)) return;
      if (text.includes("chiste")) tellJoke(wolf, sender);
      else if (text.includes("baila")) meme(wolf, 13, true, sender);
      else if (text.includes("broma")) prank(wolf, sender);
      else if (text.includes("te quiero")) say(wolf, "Yo también te quiero, {player}. Sobre todo a tu comida.", sender, { force: true });
      else if (text.includes("malo")) say(wolf, "¿Malo yo? Si soy un angelito. Con colmillos.", sender, { force: true });
      else say(wolf, pick(["¿Me llamabas? Estaba ocupado haciendo nada.", "¿Qué pasa, {player}? Habla, que te escucho.",
        "¿Hablas de mí? Todo lo que dicen es verdad. Soy genial."]), sender, { force: true });
    }, 20);
  });
}

// ------------------------------------------------------------ commands
function nearestOwnWolf(player) {
  return wolfFor(player, 64);
}

function run(player, what, arg) {
  if (what === "silencio") {
    const on = !silenced(player);
    player.setDynamicProperty("lobo:silencio", on);
    player.sendMessage(on ? "§7Tus lobos bromistas ya no escriben en el chat." : "§aTus lobos bromistas vuelven a hablar.");
    return;
  }
  if (what === "invocar") {
    const wolf = player.dimension.spawnEntity(ID, player.location);
    try {
      wolf.getComponent("minecraft:tameable")?.tame(player);
    } catch {}
    wolf.triggerEvent("lobo:domar");
    setOwner(wolf, player);
    return;
  }
  const wolf = nearestOwnWolf(player);
  if (!wolf) {
    player.sendMessage("§cNo tienes ningún Lobo Bromista cerca. Domestica uno con huesos.");
    return;
  }
  if (what === "chiste") {
    if (!tellJoke(wolf, player)) player.sendMessage("§7Tu lobo está ocupado. Espera un momento.");
  } else if (what === "broma") {
    if (!prank(wolf, player)) player.sendMessage("§7Tu lobo está ocupado. Espera un momento.");
  } else if (what === "meme") {
    if (arg && CFG.memes[String(arg)]) meme(wolf, arg, true, player);
    else randomMeme(wolf, true, player);
  }
}

const COMMANDS = [
  ["chiste", "Tu lobo bromista te cuenta un chiste"],
  ["broma", "Tu lobo bromista te gasta una broma"],
  ["meme", `Tu lobo bromista hace un meme (1-${Object.keys(CFG.memes).length}, o al azar)`],
  ["silencio", "Activa o desactiva los mensajes de tus lobos bromistas"],
];

system.beforeEvents.startup.subscribe(({ customCommandRegistry: reg }) => {
  for (const [name, description] of COMMANDS) {
    reg.registerCommand(
      {
        name: `lobo:${name}`, description, permissionLevel: CommandPermissionLevel.Any, cheatsRequired: false,
        optionalParameters: name === "meme" ? [{ type: CustomCommandParamType.Integer, name: "numero" }] : [],
      },
      (origin, arg) => {
        const player = origin.sourceEntity;
        if (player?.typeId !== "minecraft:player") {
          return { status: CustomCommandStatus.Failure, message: "Solo un jugador puede usar este comando." };
        }
        system.run(() => run(player, name, arg));
        return { status: CustomCommandStatus.Success };
      });
  }
  reg.registerCommand(
    { name: "lobo:invocar", description: "Invoca un Lobo Bromista ya domesticado",
      permissionLevel: CommandPermissionLevel.GameDirectors, cheatsRequired: true },
    (origin) => {
      const player = origin.sourceEntity;
      if (player?.typeId !== "minecraft:player") {
        return { status: CustomCommandStatus.Failure, message: "Solo un jugador puede usar este comando." };
      }
      system.run(() => run(player, "invocar"));
      return { status: CustomCommandStatus.Success };
    });
});

// The same with /scriptevent lobo:chiste, lobo:broma, lobo:meme [n], lobo:silencio
system.afterEvents.scriptEventReceive.subscribe(({ id, message, sourceEntity }) => {
  if (sourceEntity?.typeId !== "minecraft:player") return;
  const what = id.split(":")[1];
  if (["chiste", "broma", "meme", "silencio"].includes(what)) run(sourceEntity, what, parseInt(message, 10) || undefined);
}, { namespaces: ["lobo"] });
